-- Generated by src/scripts/_seed_engine_bug_queue_kinematics_1d_track_build.ts — idempotent.

INSERT INTO engine_bug_queue (bug_class, title, severity, owner_cluster, root_cause, prevention_rule, probe_type, probe_logic, status, concepts_affected, fixed_in_files, discovered_in_session, row_type) VALUES
('field3d_unknown_scenario_field_lines_crash', 'buildScenario() default-case crash on an unimplemented scenario_type — dereferencing config.field_lines.count without a guard hard-crashes the whole sim before SIM_READY, instead of degrading to the visible charge fallback (displacement_vs_distance / kinematics_1d_track, first 1D-straight-line-motion scenario)', 'CRITICAL', 'peter_parker:renderer_primitives', 'field_3d_renderer.ts''s buildScenario() switch had no case for the NEW scenario_type ''kinematics_1d_track'' (a greenfield 1D-motion scenario authored against engine_build_spec, not yet implemented in the renderer). Falling to `default:` called buildPointChargeField(charge, config.field_lines.count || 12) — but a kinematics concept authors no field_lines block at all, so config.field_lines is undefined and `.count` throws a TypeError at module-load time, before SIM_READY ever posts. Every state rendered a black canvas with no error surfaced to the player; quality_auditor caught it via a Playwright stack trace, not a visual diff. Fixed by (1) adding the missing `case "kinematics_1d_track": buildKinematics1dTrack(); break;` and (2) hardening the default-case fallback itself to `(config.field_lines && config.field_lines.count) || 12`, matching the guard pattern already used at every OTHER field_lines.count call site in this switch (lines ~7355/7834/7899/8060/11394/11907/15144/30933/31294), so a FUTURE still-unimplemented scenario_type degrades to the visible +q charge fallback instead of killing the whole sim.', 'Every field_lines.count (or any config.<block>.<field> access) inside buildScenario()''s default/fallback path MUST use the `config.X && config.X.field` guard pattern, never a bare `config.X.field` — the default case is reachable by ANY concept authored against a scenario_type this switch does not yet implement, and such a concept has no guarantee of carrying blocks (field_lines, slider_controls, …) that only make sense for the electrostatics-family scenarios the fallback was originally written for. When adding a new scenario_type, add its case in the SAME change as the concept JSON lands (per the deriveStateMeta.ts registration rule already in this spec) — never leave a concept pointing at an unimplemented scenario_type in the fleet.', 'js_eval', 'Static: grep field_3d_renderer.ts''s buildScenario() default-case block for the literal substring ''config.field_lines.count'' WITHOUT a preceding ''&&'' guard on the same statement — zero matches expected. Runtime spot-check: for every scenario_type value referenced by any concept JSON''s field_3d_config.scenario_type, assert a matching `case "<scenario_type>":` exists in the switch (a concept authored against a scenario_type with no case is a live crash risk, not just a stale-fallback risk).', 'FIXED', ARRAY['displacement_vs_distance'], ARRAY['src/lib/renderers/field_3d_renderer.ts', 'src/lib/validators/visual/deriveStateMeta.ts'], 'session_2026-07-25_kinematics_1d_track_build', 'incident')
ON CONFLICT (bug_class) DO UPDATE SET status = EXCLUDED.status, root_cause = EXCLUDED.root_cause,
  prevention_rule = EXCLUDED.prevention_rule, probe_logic = EXCLUDED.probe_logic,
  title = EXCLUDED.title, severity = EXCLUDED.severity, owner_cluster = EXCLUDED.owner_cluster,
  concepts_affected = EXCLUDED.concepts_affected, fixed_in_files = EXCLUDED.fixed_in_files,
  fixed_at = CASE WHEN EXCLUDED.status = 'FIXED' THEN now() ELSE engine_bug_queue.fixed_at END;
